          "metric": "mean_reflectance",
          "sense": "report",
          "weight": 1.0,
          "target": null,
          "region": {
            "wavelength_nm": [450.0, 700.0]
          },
          "admission_role": "score_only"
        }
      ],
      "tags": [
        "ar_coating",
        "two_layer",
        "s_polarization"
      ]
    }
